import React, { useState, useEffect, useCallback, useRef } from 'react';
import { PencilLine, Bell, ShieldCheck, ToggleLeft, ToggleRight, Lock, Mail, Upload, Camera, X, AlertTriangle } from 'lucide-react';
import './SettingsPage.css';
import { profileService } from '../services/profileService';
import { cloudinaryService } from '../services/cloudinaryService';
import { agencyDirectorService } from '../services/agencyDirectorService';

const RESET_SCOPE_OPTIONS = [
  { value: 'accounting', label: 'Accountant dashboard', description: 'Tenant payments, landlord payments, expenses, deposits, collections, cashier accounts' },
  { value: 'tenants', label: 'All tenants', description: 'Tenant profiles, leases, notes, document checklists' },
  { value: 'owners', label: 'All owners', description: 'Owner accounts, profiles, and their listed properties' },
  { value: 'properties', label: 'All properties', description: 'Managed properties, units, and marketplace listings' }
];

const SettingsPage = () => {
  const [activeTab, setActiveTab] = useState('profile');
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [notifications, setNotifications] = useState([]);
  const [userId, setUserId] = useState(null);
  const [profileForm, setProfileForm] = useState({
    name: '',
    email: '',
    company: '',
    role: '',
    status: '',
    profilePicture: ''
  });
  const [uploadingPicture, setUploadingPicture] = useState(false);
  const fileInputRef = useRef(null);
  const [passwordForm, setPasswordForm] = useState({
    currentPassword: '',
    newPassword: '',
    confirmPassword: ''
  });
  const [preferences, setPreferences] = useState({
    emailUpdates: true,
    smsAlerts: false,
    pushNotifications: true,
    weeklySummary: true,
    darkMode: false
  });

  // Settings → Reset (Agency Director only) — wipes a category of company data.
  const [resetScope, setResetScope] = useState('');
  const [resetPreview, setResetPreview] = useState(null);
  const [resetPreviewLoading, setResetPreviewLoading] = useState(false);
  const [showResetConfirm, setShowResetConfirm] = useState(false);
  const [resetPassword, setResetPassword] = useState('');
  const [resetConfirmText, setResetConfirmText] = useState('');
  const [resetSubmitting, setResetSubmitting] = useState(false);

  const addNotification = (message, type = 'info') => {
    const id = `${Date.now()}-${Math.random().toString(16).slice(2)}`;
    setNotifications((prev) => [...prev, { id, message, type }]);
    setTimeout(() => {
      setNotifications((prev) => prev.filter((n) => n.id !== id));
    }, 3000);
  };
  const loadProfile = useCallback(async () => {
    setLoading(true);
    try {
      const profile = await profileService.getProfile();
      const pictureUrl = profile.profilePictureURL || profile.profilePicture || profile.profile_picture || '';
      setProfileForm({
        name: profile.name || '',
        email: profile.email || '',
        company: profile.company || '',
        role: profile.role || '',
        status: profile.status || '',
        profilePicture: pictureUrl
      });
      if (profile.id) {
        setUserId(profile.id);
      }
      try {
        const storedUser = localStorage.getItem('user');
        if (storedUser && pictureUrl) {
          const user = JSON.parse(storedUser);
          user.profilePictureURL = pictureUrl;
          if (profile.name) user.name = profile.name;
          localStorage.setItem('user', JSON.stringify(user));
          window.dispatchEvent(new CustomEvent('userProfileUpdated'));
        }
      } catch (e) {
        console.error('Error syncing profile to localStorage:', e);
      }
    } catch (error) {
      console.error('Error loading profile:', error);
      addNotification('Failed to load profile data', 'error');
    } finally {
      setLoading(false);
    }
  }, []);
  useEffect(() => {
    loadProfile();
  }, [loadProfile]);

  const handlePasswordChange = (field, value) => {
    setPasswordForm((prev) => ({ ...prev, [field]: value }));
  };

  const handlePreferenceToggle = (field) => {
    setPreferences((prev) => ({ ...prev, [field]: !prev[field] }));
  };

  const handlePictureUpload = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const validTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/gif'];
    if (!validTypes.includes(file.type)) {
      addNotification('Please upload a valid image file (JPEG, PNG, or GIF)', 'error');
      return;
    }
    const maxSize = 5 * 1024 * 1024;
    if (file.size > maxSize) {
      addNotification('Image size must be less than 5MB', 'error');
      return;
    }

    setUploadingPicture(true);
    try {
      const result = await profileService.uploadProfilePicture(file);

      if (result.profilePictureURL) {
        setProfileForm((prev) => ({
          ...prev,
          profilePicture: result.profilePictureURL
        }));
        try {
          const storedUser = localStorage.getItem('user');
          if (storedUser) {
            const user = JSON.parse(storedUser);
            user.profilePictureURL = result.profilePictureURL;
            localStorage.setItem('user', JSON.stringify(user));
            window.dispatchEvent(new CustomEvent('userProfileUpdated'));
          }
        } catch (error) {
          console.error('Error updating localStorage:', error);
        }

        addNotification('Profile picture updated successfully', 'success');
      } else {
        addNotification('Failed to upload picture', 'error');
      }
    } catch (error) {
      console.error('Error uploading profile picture:', error);
      addNotification(error.message || 'Failed to upload profile picture', 'error');
    } finally {
      setUploadingPicture(false);
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    }
  };

  const handlePictureClick = () => {
    fileInputRef.current?.click();
  };

  const handlePasswordSubmit = async (e) => {
    e.preventDefault();

    if (passwordForm.newPassword !== passwordForm.confirmPassword) {
      addNotification('New passwords do not match', 'error');
      return;
    }

    if (passwordForm.newPassword.length < 6) {
      addNotification('Password must be at least 6 characters', 'error');
      return;
    }

    setSaving(true);
    try {
      await profileService.changePassword({
        currentPassword: passwordForm.currentPassword,
        newPassword: passwordForm.newPassword
      });

      addNotification('Password changed successfully', 'success');
      setPasswordForm({
        currentPassword: '',
        newPassword: '',
        confirmPassword: ''
      });
    } catch (error) {
      console.error('Error changing password:', error);
      addNotification('Failed to change password. Please check your current password.', 'error');
    } finally {
      setSaving(false);
    }
  };

  const isAgencyDirector = (profileForm.role || '').toLowerCase().replace(/\s+/g, '_') === 'agency_director';

  const loadResetPreview = async (scope) => {
    if (!scope) {
      setResetPreview(null);
      return;
    }
    setResetPreviewLoading(true);
    try {
      const data = await agencyDirectorService.getResetPreview(scope);
      setResetPreview(data);
    } catch (error) {
      console.error('Failed to load reset preview:', error);
      addNotification(error.message || 'Failed to load what would be reset', 'error');
      setResetPreview(null);
    } finally {
      setResetPreviewLoading(false);
    }
  };

  const handleResetScopeChange = (value) => {
    setResetScope(value);
    loadResetPreview(value);
  };

  const openResetConfirm = () => {
    if (!resetScope) return;
    setResetPassword('');
    setResetConfirmText('');
    setShowResetConfirm(true);
  };

  const handleConfirmReset = async () => {
    if (resetConfirmText.trim() !== 'RESET') {
      addNotification('Type RESET exactly to confirm.', 'error');
      return;
    }
    if (!resetPassword) {
      addNotification('Enter your password to confirm.', 'error');
      return;
    }
    setResetSubmitting(true);
    try {
      const result = await agencyDirectorService.resetData({
        scope: resetScope,
        password: resetPassword,
        confirm: resetConfirmText.trim()
      });
      addNotification(`Reset complete — ${result?.total ?? 0} record(s) deleted.`, 'success');
      setShowResetConfirm(false);
      setResetPassword('');
      setResetConfirmText('');
      loadResetPreview(resetScope);
    } catch (error) {
      console.error('Failed to reset data:', error);
      addNotification(error.message || 'Failed to reset — please try again.', 'error');
    } finally {
      setResetSubmitting(false);
    }
  };

  const renderTabs = () =>
  <div className="settings-tabs">
      <button
      type="button"
      className={`settings-tab ${activeTab === 'profile' ? 'active' : ''}`}
      onClick={() => setActiveTab('profile')}>
      
        Profile
      </button>
      <button
      type="button"
      className={`settings-tab ${activeTab === 'preferences' ? 'active' : ''}`}
      onClick={() => setActiveTab('preferences')}>
      
        Preferences
      </button>
      <button
      type="button"
      className={`settings-tab ${activeTab === 'security' ? 'active' : ''}`}
      onClick={() => setActiveTab('security')}>

        Security
      </button>
      {isAgencyDirector &&
      <button
      type="button"
      className={`settings-tab ${activeTab === 'reset' ? 'active' : ''}`}
      onClick={() => setActiveTab('reset')}
      style={activeTab === 'reset' ? undefined : { color: '#dc2626' }}>

          Reset
        </button>
      }
    </div>;


  const renderProfileForm = () =>
  <div className="settings-card">
      <div className="settings-card-header">
        <div className="settings-avatar" style={{ position: 'relative', width: '80px', height: '80px' }}>
          {profileForm.profilePicture ?
        <img
          src={profileForm.profilePicture}
          alt="Profile"
          style={{
            width: '80px',
            height: '80px',
            borderRadius: '50%',
            objectFit: 'cover',
            border: '3px solid #fff',
            boxShadow: '0 2px 8px rgba(0,0,0,0.1)'
          }} /> :


        <div style={{ width: '80px', height: '80px', borderRadius: '50%', background: 'linear-gradient(135deg, #f97316 0%, #f43f5e 100%)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#fff', fontSize: '2rem', fontWeight: 'bold' }}>
              {profileForm.name ? profileForm.name.charAt(0).toUpperCase() : 'U'}
            </div>
        }
          <button
          type="button"
          onClick={handlePictureClick}
          disabled={uploadingPicture}
          style={{
            position: 'absolute',
            bottom: '2px',
            right: '2px',
            width: '24px',
            height: '24px',
            borderRadius: '50%',
            background: '#3b82f6',
            border: '2px solid white',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            cursor: uploadingPicture ? 'not-allowed' : 'pointer',
            boxShadow: '0 2px 4px rgba(0,0,0,0.3)',
            padding: 0,
            zIndex: 10
          }}
          title="Upload profile picture">
          
            {uploadingPicture ?
          <div style={{ width: '12px', height: '12px', border: '2px solid white', borderTop: '2px solid transparent', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} /> :

          <Camera size={12} color="white" />
          }
          </button>
          <input
          ref={fileInputRef}
          type="file"
          accept="image/jpeg,image/jpg,image/png,image/gif"
          onChange={handlePictureUpload}
          style={{ display: 'none' }} />
        
        </div>
        <div className="settings-card-title">
          <h2>Profile</h2>
          <p>View your personal information and account details</p>
        </div>
      </div>

      {loading ?
    <div style={{ padding: '40px', textAlign: 'center' }}>Loading profile...</div> :

    <div className="settings-form">
          <div className="form-grid">
            <div className="form-field">
              <label>Full Name</label>
              <input
            type="text"
            value={profileForm.name || 'N/A'}
            disabled
            style={{ background: '#f3f4f6', cursor: 'not-allowed' }} />
          
            </div>
            <div className="form-field">
              <label>Email</label>
              <input
            type="email"
            value={profileForm.email || 'N/A'}
            disabled
            style={{ background: '#f3f4f6', cursor: 'not-allowed' }} />
          
            </div>
            <div className="form-field">
              <label>Company</label>
              <input
            type="text"
            value={profileForm.company || 'N/A'}
            disabled
            style={{ background: '#f3f4f6', cursor: 'not-allowed' }} />
          
            </div>
            <div className="form-field">
              <label>Role</label>
              <input
            type="text"
            value={profileForm.role || 'N/A'}
            disabled
            style={{ background: '#f3f4f6', cursor: 'not-allowed' }} />
          
            </div>
            <div className="form-field">
              <label>Status</label>
              <input
            type="text"
            value={profileForm.status || 'N/A'}
            disabled
            style={{ background: '#f3f4f6', cursor: 'not-allowed' }} />
          
            </div>
          </div>
        </div>
    }
    </div>;


  const renderPreferences = () =>
  <div className="settings-card">
      <div className="settings-card-header compact">
        <div className="settings-card-title">
          <h2>Notification Preferences</h2>
          <p>Choose what updates you want to receive</p>
        </div>
      </div>

      <div className="preferences-list">
        <div className="preference-item">
          <div className="preference-icon email">
            <Mail size={18} />
          </div>
          <div>
            <h3>Email Notifications</h3>
            <p>Receive updates and announcements via email.</p>
          </div>
          <button type="button" className="toggle-button" onClick={() => handlePreferenceToggle('emailUpdates')}>
            {preferences.emailUpdates ? <ToggleRight size={32} /> : <ToggleLeft size={32} />}
          </button>
        </div>
        <div className="preference-item">
          <div className="preference-icon sms">
            <Bell size={18} />
          </div>
          <div>
            <h3>SMS Alerts</h3>
            <p>Get instant alerts for important account activity.</p>
          </div>
          <button type="button" className="toggle-button" onClick={() => handlePreferenceToggle('smsAlerts')}>
            {preferences.smsAlerts ? <ToggleRight size={32} /> : <ToggleLeft size={32} />}
          </button>
        </div>
        <div className="preference-item">
          <div className="preference-icon push">
            <ShieldCheck size={18} />
          </div>
          <div>
            <h3>Push Notifications</h3>
            <p>Allow notifications when you're working in the app.</p>
          </div>
          <button type="button" className="toggle-button" onClick={() => handlePreferenceToggle('pushNotifications')}>
            {preferences.pushNotifications ? <ToggleRight size={32} /> : <ToggleLeft size={32} />}
          </button>
        </div>
        <div className="preference-item">
          <div className="preference-icon summary">
            <Bell size={18} />
          </div>
          <div>
            <h3>Weekly Summary</h3>
            <p>Receive a summary of your activity every Monday.</p>
          </div>
          <button type="button" className="toggle-button" onClick={() => handlePreferenceToggle('weeklySummary')}>
            {preferences.weeklySummary ? <ToggleRight size={32} /> : <ToggleLeft size={32} />}
          </button>
        </div>
        <div className="preference-item">
          <div className="preference-icon theme">
            <ShieldCheck size={18} />
          </div>
          <div>
            <h3>Dark Mode</h3>
            <p>Reduce eye strain with a dark color palette.</p>
          </div>
          <button type="button" className="toggle-button" onClick={() => handlePreferenceToggle('darkMode')}>
            {preferences.darkMode ? <ToggleRight size={32} /> : <ToggleLeft size={32} />}
          </button>
        </div>
      </div>
    </div>;


  const renderSecurity = () =>
  <div className="settings-card">
      <div className="settings-card-header compact">
        <div className="settings-card-title">
          <h2>Security Settings</h2>
          <p>Manage your password, authentication and sessions</p>
        </div>
      </div>

      <form className="settings-form" onSubmit={handlePasswordSubmit}>
        <div className="form-grid">
          <div className="form-field">
            <label>Current Password</label>
            <input
            type="password"
            value={passwordForm.currentPassword}
            onChange={(e) => handlePasswordChange('currentPassword', e.target.value)}
            required
            disabled={saving}
            placeholder="Enter your current password" />
          
          </div>
          <div className="form-field">
            <label>New Password</label>
            <input
            type="password"
            value={passwordForm.newPassword}
            onChange={(e) => handlePasswordChange('newPassword', e.target.value)}
            required
            disabled={saving}
            placeholder="Enter your new password"
            minLength={6} />
          
          </div>
          <div className="form-field">
            <label>Confirm New Password</label>
            <input
            type="password"
            value={passwordForm.confirmPassword}
            onChange={(e) => handlePasswordChange('confirmPassword', e.target.value)}
            required
            disabled={saving}
            placeholder="Confirm your new password"
            minLength={6} />
          
          </div>
        </div>
        <div className="form-actions">
          <button type="submit" className="btn-primary" disabled={saving}>
            {saving ? 'Changing Password...' : 'Change Password'}
          </button>
        </div>
      </form>

      <div className="security-list" style={{ marginTop: '40px' }}>
        <div className="security-item">
          <div className="security-icon">
            <ShieldCheck size={18} />
          </div>
          <div>
            <h3>Two-factor Authentication</h3>
            <p>Add an extra layer of security to your account.</p>
          </div>
          <button type="button" className="btn-primary ghost">Enable</button>
        </div>
        <div className="security-item">
          <div className="security-icon">
            <Bell size={18} />
          </div>
          <div>
            <h3>Login Alerts</h3>
            <p>Receive a notification when a new device signs in.</p>
          </div>
          <button type="button" className="btn-secondary">Manage</button>
        </div>
      </div>
    </div>;


  const renderReset = () =>
  <div className="settings-card">
      <div className="settings-card-header compact">
        <div className="settings-card-title">
          <h2 style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <AlertTriangle size={20} color="#dc2626" /> Reset data
          </h2>
          <p>Permanently delete a whole category of your company's data. This cannot be undone.</p>
        </div>
      </div>

      <div className="settings-form">
        <div className="form-field" style={{ maxWidth: '480px' }}>
          <label>What do you want to reset?</label>
          <select
          value={resetScope}
          onChange={(e) => handleResetScopeChange(e.target.value)}
          disabled={resetSubmitting}
          style={{ padding: '10px 12px', borderRadius: '8px', border: '1px solid #d1d5db', fontSize: '0.9rem', width: '100%' }}>
            <option value="">— Select a category —</option>
            {RESET_SCOPE_OPTIONS.map((opt) =>
          <option key={opt.value} value={opt.value}>{opt.label}</option>
          )}
          </select>
          {resetScope &&
        <p style={{ margin: '8px 0 0', fontSize: '0.82rem', color: '#6b7280' }}>
              {RESET_SCOPE_OPTIONS.find((o) => o.value === resetScope)?.description}
            </p>
        }
        </div>

        {resetScope &&
      <div style={{ marginTop: '20px', padding: '16px', borderRadius: '10px', background: '#fef2f2', border: '1px solid #fecaca', maxWidth: '480px' }}>
            {resetPreviewLoading ?
        <p style={{ margin: 0, color: '#6b7280', fontSize: '0.85rem' }}>Checking what would be deleted…</p> :
        resetPreview && resetPreview.total > 0 ?
        <>
                <p style={{ margin: '0 0 8px', fontWeight: 700, color: '#991b1b' }}>
                  This will permanently delete {resetPreview.total} record{resetPreview.total === 1 ? '' : 's'}:
                </p>
                <ul style={{ margin: 0, paddingLeft: '18px', color: '#7f1d1d', fontSize: '0.85rem' }}>
                  {Object.entries(resetPreview.counts || {}).map(([label, n]) =>
            <li key={label}>{label}: {n}</li>
            )}
                </ul>
              </> :

        <p style={{ margin: 0, color: '#166534', fontSize: '0.85rem' }}>Nothing to delete — this category is already empty.</p>
        }
          </div>
      }

        <div className="form-actions">
          <button
          type="button"
          className="btn-primary"
          style={{ background: '#dc2626' }}
          disabled={!resetScope || resetPreviewLoading || !resetPreview || resetPreview.total === 0}
          onClick={openResetConfirm}>

            Reset this data
          </button>
        </div>
      </div>

      {showResetConfirm &&
    <div
      style={{ position: 'fixed', inset: 0, background: 'rgba(15,23,42,0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}
      onClick={() => !resetSubmitting && setShowResetConfirm(false)}>

          <div
        style={{ background: '#fff', borderRadius: '14px', padding: '28px', maxWidth: '440px', width: '90%', boxShadow: '0 12px 40px rgba(0,0,0,0.2)' }}
        onClick={(e) => e.stopPropagation()}>

            <h3 style={{ margin: '0 0 8px', display: 'flex', alignItems: 'center', gap: '8px', color: '#991b1b' }}>
              <AlertTriangle size={20} /> Confirm reset
            </h3>
            <p style={{ margin: '0 0 16px', color: '#374151', fontSize: '0.9rem' }}>
              You're about to permanently delete <strong>{resetPreview?.total ?? 0}</strong> record(s) under
              {' '}<strong>{RESET_SCOPE_OPTIONS.find((o) => o.value === resetScope)?.label}</strong>. This cannot be undone.
            </p>

            <div className="form-field" style={{ marginBottom: '14px' }}>
              <label>Type RESET to confirm</label>
              <input
            type="text"
            value={resetConfirmText}
            onChange={(e) => setResetConfirmText(e.target.value)}
            placeholder="RESET"
            disabled={resetSubmitting}
            style={{ padding: '10px 12px', borderRadius: '8px', border: '1px solid #d1d5db', fontSize: '0.9rem', width: '100%', boxSizing: 'border-box' }} />

            </div>
            <div className="form-field" style={{ marginBottom: '20px' }}>
              <label>Your password</label>
              <input
            type="password"
            value={resetPassword}
            onChange={(e) => setResetPassword(e.target.value)}
            placeholder="Enter your account password"
            disabled={resetSubmitting}
            style={{ padding: '10px 12px', borderRadius: '8px', border: '1px solid #d1d5db', fontSize: '0.9rem', width: '100%', boxSizing: 'border-box' }} />

            </div>

            <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px' }}>
              <button type="button" className="btn-secondary" disabled={resetSubmitting} onClick={() => setShowResetConfirm(false)}>
                Cancel
              </button>
              <button
            type="button"
            className="btn-primary"
            style={{ background: '#dc2626' }}
            disabled={resetSubmitting || resetConfirmText.trim() !== 'RESET' || !resetPassword}
            onClick={handleConfirmReset}>

                {resetSubmitting ? 'Deleting…' : 'Permanently delete'}
              </button>
            </div>
          </div>
        </div>
    }
    </div>;


  return (
    <div className="settings-page">
      {notifications.length > 0 &&
      <div style={{ position: 'fixed', top: '20px', right: '20px', zIndex: 1000 }}>
          {notifications.map((notification) =>
        <div
          key={notification.id}
          style={{
            padding: '12px 20px',
            marginBottom: '10px',
            borderRadius: '8px',
            background: notification.type === 'success' ? '#10b981' : notification.type === 'error' ? '#ef4444' : '#3b82f6',
            color: '#fff',
            boxShadow: '0 4px 12px rgba(0,0,0,0.15)',
            minWidth: '300px'
          }}>
          
              {notification.message}
            </div>
        )}
        </div>
      }
      {renderTabs()}
      {activeTab === 'profile' && renderProfileForm()}
      {activeTab === 'preferences' && renderPreferences()}
      {activeTab === 'security' && renderSecurity()}
      {activeTab === 'reset' && isAgencyDirector && renderReset()}
    </div>);

};

export default SettingsPage;
